pub fn parse_entry(entry: &str, index: usize) -> Result<String, String> {
    let entry = entry.trim();
    if entry.is_empty()
        || !entry
            .bytes()
            .all(|c| c.is_ascii_lowercase() || c.is_ascii_digit() || c == b'_' || c == b'-')
    {
        Err(format!("feature entry {index} invalid: {entry}"))
    } else {
        Ok(entry.to_string())
    }
}

pub fn parse_feature(setting: Option<&str>) -> Result<Vec<String>, String> {
    let Some(setting) = setting else {
        return Ok(vec!["search".into(), "labels".into()]);
    };
    if setting.is_empty() {
        return Ok(Vec::new());
    }
    setting
        .split(',')
        .enumerate()
        .map(|(index, entry)| parse_entry(entry, index))
        .collect()
}

