#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Entry { pub id: u64, pub priority: i32, pub created: u64 }

fn sorted(entries: &[Entry]) -> Vec<Entry> {
    let mut result = entries.to_vec();
    result.sort_by(|a, b| {
        b.priority
            .cmp(&a.priority)
            .then(a.created.cmp(&b.created))
            .then(a.id.cmp(&b.id))
    });
    result
}

pub fn ordered(entries: &[Entry], minimum: Option<i32>) -> Vec<Entry> {
    sorted(entries)
        .into_iter()
        .filter(|entry| minimum.is_none_or(|minimum| entry.priority >= minimum))
        .collect()
}

pub fn page(
    entries: &[Entry],
    after: Option<(i32, u64, u64)>,
    limit: usize,
    minimum: Option<i32>,
) -> Vec<Entry> {
    sorted(entries)
        .into_iter()
        .filter(|entry| minimum.is_none_or(|minimum| entry.priority >= minimum))
        .filter(|entry| {
            after.is_none_or(|(priority, created, id)| {
                entry.priority < priority
                    || (entry.priority == priority && (entry.created, entry.id) > (created, id))
            })
        })
        .take(limit)
        .collect()
}

