#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Lookup {
    Ready(Vec<String>),
    Unavailable,
}

pub fn fallback(value: &Lookup) -> bool {
    matches!(value, Lookup::Unavailable)
}

pub fn render(value: &Lookup) -> String {
    match value {
        Lookup::Ready(items) if items.is_empty() => "No results".into(),
        Lookup::Ready(items) => items.join(", "),
        Lookup::Unavailable => "Lookup unavailable".into(),
    }
}

pub fn display_field(value: &Lookup, limit: usize) -> String {
    render(value).chars().take(limit).collect()
}

